'use strict';

// User content stays separate from the synthetic scenarios. Secrets are server-only.
let messageDraft='', messageContext='', messageResult=null, messageBusy=false, messageError='';
let qrResult=null, qrDraft='', qrError='', qrBusy=false, cameraStream=null, cameraTimer=null, cameraGeneration=0;
let lastContentResult=null;
const verdictLabel=v=>({likely_scam:t('Likely scam','संभावित धोखाधड़ी'),suspicious:t('Suspicious · verify first','संदिग्ध · पहले पुष्टि करें'),no_clear_scam_signals:t('No clear scam signals','कोई स्पष्ट धोखाधड़ी संकेत नहीं'),insufficient_context:t('More context needed','और संदर्भ चाहिए'),unverified:t('Decoded · unverified','पढ़ा गया · अपुष्ट')}[v]||v);
const singleAttemptAPI=api;
api=async function(path,method='GET',body){for(let attempt=0;;attempt++){try{return await singleAttemptAPI(path,method,body);}catch(error){if(method!=='GET'||attempt>=2||(error.status&&![502,503,504].includes(error.status)))throw error;await new Promise(resolve=>setTimeout(resolve,1000));}}};
const contentTitle=r=>r.kind==='message'?t('Message check','संदेश जाँच'):t('QR inspection','QR जाँच');

// History is authoritative on the backend; only display preferences are cached locally.
persist=function(){try{localStorage.setItem(key,JSON.stringify({...state,records:[]}));}catch{if(!storageWarned){storageWarned=true;toast('Display preferences could not be saved in this browser.');}}};

const baseConsumerPage=consumerPage;
consumerPage=function(){if(page==='messages')return messagePage();return baseConsumerPage();};
const connectedRender=render;
render=function(){if(!(view==='consumer'&&page==='check'&&mode==='qr'&&!flow))stopCamera();connectedRender();const status=$('.service-status.connected span');const connecting=$('.service-status.connecting span');if(connecting)connecting.textContent=t('Connecting to checks… Free hosting may take about a minute to wake up.','जाँच सेवा से जुड़ रहे हैं… मुफ़्त सर्वर शुरू होने में लगभग एक मिनट लग सकता है।');if(status)status.textContent=t('Payment checks online','भुगतान जाँच ऑनलाइन')+(backendMetrics?.message_analysis_configured?t(' · AI message checks configured',' · AI संदेश जाँच कॉन्फ़िगर की गई है'):'')+(backendMetrics?.ephemeral_storage?t(' · Free hosting: history may reset after a restart.',' · मुफ़्त होस्टिंग: रीस्टार्ट के बाद इतिहास मिट सकता है।'):'');};
const connectedNavigate=navigate;
navigate=function(next){stopCamera();if(next==='check'){flow=null;assessment=null;flowStep='input';mode='qr';}connectedNavigate(next);};
const connectedHome=home;
home=function(){return connectedHome().replace('data-start="request"','data-action="open-message"').replace('Add payment message',t('Check a message','संदेश जाँचें')).replace('Make sense of a request',t('Spot scam signals in any message','संदेश में धोखाधड़ी के संकेत देखें')).replace('Paste a demo payment link',t('Paste a UPI link or website address','UPI लिंक या वेबसाइट पता पेस्ट करें')).replace('Demo links only. No money moves.',t('Links are inspected. No payment is made.','लिंक की जाँच होती है। कोई भुगतान नहीं।')).replace('https://pay.demo/refund','upi://pay?pa=shop@upi&pn=Shop').replace('Only demo details you choose to submit are sent to the payment-check service. Your other apps stay private.',t('Only content you submit is analyzed. Messages go to OpenAI through our backend; QR images stay in your browser.','केवल आपके भेजे विवरण जाँचे जाते हैं। संदेश सर्वर के ज़रिए OpenAI को जाते हैं; QR तस्वीरें ब्राउज़र में रहती हैं।'));};
actions['open-message']=()=>{view='consumer';navigate('messages');};

function messagePage(){return `<div class="flow-container tool-container"><button class="back" data-page="home">${icon('back')}${t('Back to home','होम पर वापस')}</button><div class="flow-heading"><div class="eyebrow">${icon('message')} ${t('UNDERSTAND THE MESSAGE','संदेश को समझें')}</div><h1>${t('Real request or scam attempt?','असली अनुरोध या धोखाधड़ी?')}</h1><p>${t('Paste a message from SMS, WhatsApp, email, or a payment request. Look at the evidence before you act.','SMS, WhatsApp, ईमेल या भुगतान अनुरोध का संदेश पेस्ट करें। कदम उठाने से पहले संकेत समझें।')}</p></div><section class="card form-card"><form id="message-check-form" aria-busy="${messageBusy}"><label class="field-label" for="scam-message">${t('Message to check','जाँचने वाला संदेश')}</label><textarea id="scam-message" name="message" maxlength="5000" minlength="3" required ${messageBusy?'disabled':''} placeholder="${t('Paste the full message here…','पूरा संदेश यहाँ पेस्ट करें…')}">${esc(messageDraft)}</textarea><div class="input-meta"><span>${t('Remove OTPs, passwords and private details.','OTP, पासवर्ड और निजी विवरण हटाएँ।')}</span><span id="message-count">${messageDraft.length}/5000</span></div><div class="form-row"><label class="field-label" for="message-context">${t('Anything else we should know?','कोई और संदर्भ?')} <span class="optional">${t('(optional)','(वैकल्पिक)')}</span></label><input id="message-context" name="context" maxlength="1000" ${messageBusy?'disabled':''} value="${esc(messageContext)}" placeholder="${t('e.g. I was expecting a refund from this shop','जैसे: मुझे इस दुकान से रिफंड मिलना था')}"></div><div class="info-note">${icon('lock')}<span>${t('The text you submit is sent to OpenAI for analysis and saved in your private check history. It cannot prove the sender’s identity.','आपका भेजा पाठ OpenAI को जाँच के लिए जाता है और निजी इतिहास में सेव होता है। इससे भेजने वाले की पहचान प्रमाणित नहीं होती।')}</span></div>${messageError?`<p class="error" role="alert">${esc(messageError)}</p>`:''}<div class="button-row"><button class="btn" type="submit" ${messageBusy?'disabled':''}>${messageBusy?`<span class="small-spinner"></span> ${t('Analyzing message…','संदेश जाँचा जा रहा है…')}`:t('Check message','संदेश जाँचें')}${icon('arrow')}</button><button class="btn secondary" type="button" data-action="clear-message" ${messageBusy?'disabled':''}>${t('Clear','हटाएँ')}</button></div></form></section>${messageResult?contentResult(messageResult):`<div class="tool-hint">${icon('info')}<p>${t('You’ll see a risk assessment, exact warning signs, and practical next steps. Even a normal-looking message needs independent verification.','आपको जोखिम आकलन, चेतावनी के संकेत और अगले कदम दिखेंगे। सामान्य दिखने वाले संदेश की भी स्वतंत्र पुष्टि करें।')}</p></div>`}${footer()}</div>`;}

function contentResult(result){const details=result.details||{},isQR=result.kind==='qr';return `<section class="card content-result ${result.risk}" id="content-result" data-content-id="${esc(result.id)}" aria-live="polite"><div class="result-kicker">${icon(isQR?'scan':'shield')} ${contentTitle(result)} <span>${esc(result.provider)}${result.model?' · '+esc(result.model):''}</span></div>${pill(result.risk,isQR?(result.risk==='high'?t('High risk link','उच्च जोखिम लिंक'):t('Decoded · verify before use','पढ़ा गया · उपयोग से पहले पुष्टि करें')):verdictLabel(result.verdict))}<h2>${esc(result.summary)}</h2>${isQR?`<div class="decoded-content"><small>${t('DECODED CONTENT','QR में मिला विवरण')} · ${esc(result.qr_type)}</small><pre>${esc(result.payload)}</pre><button class="text-link" data-action="copy-qr">${t('Copy decoded content','मिला विवरण कॉपी करें')}</button></div>${Object.keys(details).length?`<div class="field-grid tool-details">${Object.entries(details).filter(([,v])=>v!==null&&v!=='').map(([k,v])=>`<div class="detail-pair"><small>${esc(k.replaceAll('_',' '))}</small><strong>${k==='amount'?money(v):esc(v)}</strong></div>`).join('')}</div>`:''}`:''}${result.red_flags.length?`<h3>${t('What needs attention','ध्यान देने योग्य संकेत')}</h3><ul class="signal-list">${result.red_flags.map(f=>`<li>${icon('alert')}<div><strong>${esc(f.signal)}</strong><p>${esc(f.evidence)}</p></div></li>`).join('')}</ul>`:''}${result.reassuring_signals?.length?`<h3>${t('What looks ordinary','सामान्य लगने वाली बातें')}</h3><ul class="plain-list">${result.reassuring_signals.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`:''}<h3>${t('What to do next','अगले कदम')}</h3><ol class="next-steps">${result.next_steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><details class="explain"><summary>${t('What this check cannot confirm','यह जाँच क्या प्रमाणित नहीं कर सकती')}</summary>${result.limitations.map(s=>`<p>${esc(s)}</p>`).join('')}</details><div class="button-row">${isQR&&result.qr_type==='upi'?btn(t('Review payment details','भुगतान विवरण देखें'),'qr-payment','','arrow'):''}${isQR&&!['wifi','contact'].includes(result.qr_type)?btn(t('Analyze as a message','संदेश की तरह जाँचें'),'qr-as-message','secondary','message'):''}${btn(t('Download result','नतीजा डाउनलोड करें'),'export-check','secondary','download')}<button class="text-link" data-investigate="${esc(result.id)}">${t('Open saved record','सेव रिकॉर्ड देखें')}${icon('arrow')}</button></div><p class="microcopy">${Number.isFinite(result.latency_ms)?`Analysis time: ${(result.latency_ms/1000).toFixed(1)} s · `:''}${t('Saved to your backend check history. Risk indicators are not proof of fraud or authenticity.','आपके सर्वर इतिहास में सेव। जोखिम संकेत धोखाधड़ी या प्रामाणिकता का प्रमाण नहीं हैं।')}</p></section>`;}

async function checkMessage(){if(messageBusy)return;messageDraft=$('#scam-message')?.value.trim()||messageDraft.trim();messageContext=$('#message-context')?.value.trim()||'';if(messageDraft.length<3){messageError=t('Paste at least 3 characters.','कम से कम 3 अक्षर पेस्ट करें।');render();return;}messageBusy=true;messageError='';messageResult=null;render();try{const result=await api('/analyze-message','POST',{message:messageDraft,context:messageContext,language:state.language});messageResult=result;lastContentResult=result;state.records=[result.record,...state.records.filter(r=>r.id!==result.id)];await refreshBackend(false);}catch(error){messageError=error.message;}finally{messageBusy=false;if(page==='messages'||(page==='check'&&mode==='message')){render();if(messageResult)$('#content-result')?.scrollIntoView({behavior:'smooth',block:'start'});}}}
actions['clear-message']=()=>{if(messageBusy)return;messageDraft='';messageContext='';messageResult=null;messageError='';render();$('#scam-message')?.focus();};

function qrPage(){return `<div class="flow-container tool-container"><button class="back" data-page="home">${icon('back')}${t('Back to home','होम पर वापस')}</button><div class="flow-heading"><div class="eyebrow">${icon('scan')} ${t('LOOK INSIDE THE CODE','कोड का विवरण देखें')}</div><h1>${t('Scan it. Understand it.','स्कैन करें। समझें।')}</h1><p>${t('Read a QR from an image or your camera. UPI payments, websites, Wi-Fi, contacts, and text all have a place here.','तस्वीर या कैमरे से QR पढ़ें। UPI भुगतान, वेबसाइट, Wi-Fi, संपर्क और पाठ का विवरण देखें।')}</p></div><section class="card form-card"><div class="tabs tool-tabs"><button class="tab active" data-mode="qr">${icon('scan')}${t('Scan QR','QR स्कैन')}</button><button class="tab" data-mode="link">${icon('link')}${t('Payment link','भुगतान लिंक')}</button><button class="tab" data-action="open-message">${icon('message')}${t('Check message','संदेश जाँच')}</button></div><div class="qr-upload"><input id="qr-image" type="file" accept="image/*" aria-label="Upload QR image" ${qrBusy?'disabled':''}><label for="qr-image" class="upload-area">${icon('upload')}<strong>${t('Choose a QR image','QR तस्वीर चुनें')}</strong><small>${t('PNG, JPG, WebP or another browser-readable image · up to 10 MB','PNG, JPG, WebP या समर्थित तस्वीर · 10 MB तक')}</small></label></div><div class="camera-controls"><button class="btn secondary" data-action="start-camera" ${qrBusy?'disabled':''}>${icon('scan')}${t('Use camera','कैमरा इस्तेमाल करें')}</button><span>${t('Your image stays on this device.','आपकी तस्वीर इसी डिवाइस पर रहती है।')}</span></div><div id="camera-panel" hidden><video id="qr-camera" muted playsinline aria-label="QR camera preview"></video><p id="camera-status" role="status">${t('Point your camera at a QR code.','कैमरा QR कोड की ओर करें।')}</p><button class="btn secondary" data-action="stop-camera">${t('Stop camera','कैमरा बंद करें')}</button></div><details class="explain qr-text-entry"><summary>${t('Already have the QR text or a UPI link?','QR का पाठ या UPI लिंक पहले से है?')}</summary><form id="qr-payload-form"><label class="field-label" for="qr-payload">${t('Paste decoded QR content','QR का पाठ पेस्ट करें')}</label><textarea id="qr-payload" maxlength="8192" required placeholder="upi://pay?pa=shop@upi&pn=Shop">${esc(qrDraft)}</textarea><button class="btn secondary" type="submit" ${qrBusy?'disabled':''}>${t('Inspect content','विवरण जाँचें')}${icon('arrow')}</button></form></details><div id="qr-status" role="status">${qrBusy?`<p class="tool-hint"><span class="small-spinner"></span>${t('Reading QR content…','QR विवरण पढ़ रहे हैं…')}</p>`:''}</div>${qrError?`<p class="error" role="alert">${esc(qrError)}</p>${qrDraft?`<div class="decoded-content"><small>Last supplied QR text</small><pre>${esc(qrDraft)}</pre></div>`:''}`:''}<div class="info-note">${icon('lock')}<span>${t('Only decoded text is sent to the backend. Links are never opened automatically. A readable QR is not proof of a genuine recipient.','केवल QR का पाठ सर्वर को जाता है। लिंक अपने आप नहीं खुलते। QR पढ़ पाने से प्राप्तकर्ता प्रमाणित नहीं होता।')}</span></div><div class="button-row">${btn(t('Try a synthetic scenario','डेमो उदाहरण आज़माएँ'),'scenarios','text-link')}</div></section>${qrResult?contentResult(qrResult):''}${footer()}</div>`;}

function stopCamera(){cameraGeneration++;clearTimeout(cameraTimer);cameraTimer=null;if(cameraStream){cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null;}const video=$('#qr-camera');if(video)video.srcObject=null;const panel=$('#camera-panel');if(panel)panel.hidden=true;}
async function decodeQR(source){const width=source.videoWidth||source.naturalWidth||source.width,height=source.videoHeight||source.naturalHeight||source.height;if(!width||!height)return null;const scale=Math.min(1,1800/Math.max(width,height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(width*scale));canvas.height=Math.max(1,Math.round(height*scale));const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(source,0,0,canvas.width,canvas.height);if('BarcodeDetector' in window){try{const found=await new BarcodeDetector({formats:['qr_code']}).detect(canvas);if(found[0]?.rawValue)return found[0].rawValue;}catch{/* jsQR supports browsers without native QR detection. */}}const image=ctx.getImageData(0,0,canvas.width,canvas.height);const result=jsQR(image.data,image.width,image.height,{inversionAttempts:'attemptBoth'});return result?.data||null;}
async function inspectQR(payload){if(qrBusy)return;stopCamera();qrDraft=payload;qrResult=null;qrError='';qrBusy=true;render();try{const result=await api('/analyze-qr','POST',{payload});qrResult=result;lastContentResult=result;state.records=[result.record,...state.records.filter(r=>r.id!==result.id)];await refreshBackend(false);}catch(error){qrError=error.message;}finally{qrBusy=false;if(page==='check'&&mode==='qr'&&!flow){render();if(qrResult)$('#content-result')?.scrollIntoView({behavior:'smooth',block:'start'});}}}
async function scanImage(file){if(!file||qrBusy)return;stopCamera();qrError='';qrResult=null;if(file.size>10*1024*1024){qrError=t('Choose an image smaller than 10 MB.','10 MB से छोटी तस्वीर चुनें।');render();return;}if(!file.type.startsWith('image/')){qrError=t('Choose an image file containing a QR code.','QR वाली तस्वीर चुनें।');render();return;}qrBusy=true;render();let image;const blobUrl=URL.createObjectURL(file);try{image=new Image();image.src=blobUrl;await image.decode();const payload=await decodeQR(image);if(!payload)throw new Error(t('No readable QR found. Try a sharper image showing the full code and its border.','QR पढ़ा नहीं जा सका। पूरे कोड और किनारे वाली साफ तस्वीर चुनें।'));qrBusy=false;await inspectQR(payload);}catch(error){qrError=error.name==='EncodingError'?t('This image format could not be opened. Convert it to PNG or JPG.','यह तस्वीर नहीं खुली। PNG या JPG में बदलें।'):error.message;qrBusy=false;render();}finally{URL.revokeObjectURL(blobUrl);}}
actions['start-camera']=async()=>{if(qrBusy)return;stopCamera();const generation=cameraGeneration;if(!navigator.mediaDevices?.getUserMedia){qrError=t('Camera access is unavailable in this browser. Upload a QR image instead.','इस ब्राउज़र में कैमरा उपलब्ध नहीं है। QR तस्वीर अपलोड करें।');render();return;}try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280}},audio:false});if(generation!==cameraGeneration||page!=='check'||mode!=='qr'){stream.getTracks().forEach(t=>t.stop());return;}cameraStream=stream;$('#camera-panel').hidden=false;const video=$('#qr-camera');video.srcObject=stream;await video.play();const frame=async()=>{if(generation!==cameraGeneration||!cameraStream||!video.isConnected)return;try{const payload=await decodeQR(video);if(payload){await inspectQR(payload);return;}}catch{const label=$('#camera-status');if(label)label.textContent=t('Could not read this frame. Keep the QR steady.','QR स्थिर रखें।');}cameraTimer=setTimeout(frame,300);};cameraTimer=setTimeout(frame,300);}catch(error){stopCamera();qrError=error.name==='NotAllowedError'?t('Camera permission was denied. Allow camera access in your browser settings or upload an image.','कैमरा अनुमति नहीं मिली। ब्राउज़र सेटिंग्स से अनुमति दें या तस्वीर अपलोड करें।'):t('No usable camera was found. Upload a QR image instead.','कैमरा उपलब्ध नहीं है। QR तस्वीर अपलोड करें।');render();}};
actions['stop-camera']=stopCamera;
actions['qr-picker']=()=>{flow=null;assessment=null;flowStep='input';mode='qr';navigate('check');};
actions['copy-qr']=async()=>{try{await navigator.clipboard.writeText((lastContentResult?.kind==='qr'?lastContentResult:qrResult)?.payload||'');toast(t('Decoded content copied.','विवरण कॉपी हुआ।'));}catch{toast(t('Clipboard unavailable. Select and copy the decoded text.','क्लिपबोर्ड उपलब्ध नहीं। पाठ चुनकर कॉपी करें।'));}};
actions['qr-as-message']=()=>{messageDraft=((lastContentResult?.kind==='qr'?lastContentResult:qrResult)?.payload||'').slice(0,5000);messageContext='Content decoded from a QR code.';messageResult=null;messageError='';view='consumer';navigate('messages');};
actions['export-check']=()=>{const result=lastContentResult||messageResult||qrResult;if(!result)return;downloadJSON('upi-guard-check-'+result.id+'.json',{...result,record:undefined});};
function downloadJSON(filename,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('Result downloaded.','नतीजा डाउनलोड हुआ।'));}

function userFlow(details,payload){view='consumer';flow={id:'custom',source:'user',recipient:details.recipient==='Not supplied'?'Unverified recipient':details.recipient,account:details.account,amount:details.amount||null,originalAmount:details.amount||null,expected:null,purpose:details.note||'User-supplied UPI payment request',currency:'INR',session:crypto.randomUUID(),message:details.note||'',intent:'pay',link:payload,reference:'No bank or independent merchant verification',ref:'unavailable'};assessment=null;formError='';missingContext=false;flowStep='input';page='check';mode='link';render();window.scrollTo(0,0);}
function linkPage(){return `<div class="flow-container tool-container"><button class="back" data-page="home">${icon('back')}${t('Back to home','होम पर वापस')}</button><div class="flow-heading"><h1>${t('Look closer at the link.','लिंक का विवरण समझें।')}</h1><p>${t('Read a UPI payment request or check the wording of a website address. Links are never opened automatically.','UPI अनुरोध या वेबसाइट पते की जाँच करें। लिंक अपने आप नहीं खुलते।')}</p></div><section class="card form-card"><div class="tabs tool-tabs"><button class="tab" data-mode="qr">${icon('scan')}${t('Scan QR','QR स्कैन')}</button><button class="tab active" data-mode="link">${icon('link')}${t('Payment link','भुगतान लिंक')}</button><button class="tab" data-action="open-message">${icon('message')}${t('Check message','संदेश जाँच')}</button></div><form id="inspect-link-form"><label class="field-label" for="inspect-link">${t('UPI link or website address','UPI लिंक या वेबसाइट पता')}</label><input id="inspect-link" name="link" type="text" maxlength="8192" required placeholder="upi://pay?pa=shop@upi&pn=Shop">${formError?`<p class="error" role="alert">${esc(formError)}</p>`:''}<div class="info-note" style="margin-top:18px">${icon('info')}${t('A link’s text cannot prove that its owner is genuine. Website addresses open in the message checker for review; no website content is fetched.','लिंक का पाठ उसके मालिक को प्रमाणित नहीं करता। वेबसाइट पता संदेश जाँच में खुलता है; वेबसाइट नहीं खोली जाती।')}</div><div class="button-row"><button class="btn" type="submit">${t('Read link details','लिंक विवरण पढ़ें')}${icon('arrow')}</button>${btn(t('Try a demo scenario','डेमो आज़माएँ'),'scenarios','secondary')}</div></form></section></div>`;}
actions['qr-payment']=()=>{const r=lastContentResult?.kind==='qr'?lastContentResult:qrResult;if(r?.qr_type==='upi')userFlow(r.details,r.payload);};
const scenarioReadLink=readLink;
readLink=function(value){if(parseDemoLink(value))return scenarioReadLink(value);const raw=value.trim();let url;try{url=new URL(raw);}catch{formError=t('Paste a complete UPI link or website address.','पूरा UPI लिंक या वेबसाइट पता पेस्ट करें।');page='check';mode='link';flowStep='input';render();return false;}if(url.protocol==='upi:'){flow=null;assessment=null;mode='qr';page='check';flowStep='input';inspectQR(raw);return false;}if(['https:','http:'].includes(url.protocol)){messageDraft=raw;messageContext='Please inspect this website address. No website visit or sender verification has been performed.';messageResult=null;messageError='';navigate('messages');return false;}formError=t('This link type is not supported. Use the QR inspector to read its content safely.','यह लिंक प्रकार समर्थित नहीं है। QR जाँच से विवरण पढ़ें।');page='check';mode='link';render();return false;};

const scenarioCheckPage=checkPage;
checkPage=function(){if(flowStep==='input'&&mode==='qr'&&!flow)return qrPage();if(flowStep==='input'&&mode==='link'&&!flow)return linkPage();if(flowStep==='input'&&mode==='message')return messagePage();let html=scenarioCheckPage();if(flow?.source==='user'){html=html.replaceAll('Synthetic demo','User-supplied · unverified').replaceAll('Demo account','UPI address').replaceAll('demo payment','payment request').replaceAll('Demo payment link','UPI payment link').replace('Amount</small><strong>'+money(flow.amount)+'</strong>','Amount</small><strong>'+money(flow.amount)+'</strong>');if(flowStep==='input'){html=html.replace('<form id="check-form">','<form id="user-payment-form">');html=html.replace(/<input name="link" id="payment-link"[^>]*>/,`<input name="link" id="payment-link" readonly value="${esc(flow.link)}">`).replace(/<button class="text-link" type="button" data-action="load-link"[\s\S]*?<\/p>/,'');html=html.replace('<div class="form-row"><label for="payment-message"',`<div class="form-row"><label class="field-label" for="user-amount">${t('Amount to inspect (INR)','जाँच की राशि (INR)')}</label><input id="user-amount" type="number" min="0.01" max="1000000" step="0.01" required value="${flow.amount||''}" placeholder="Enter the amount you intend to pay"></div><div class="form-row"><label for="payment-message"`);}html=html.replace(/<button class="btn[^\"]*" data-action="complete-payment">[\s\S]*?<\/button>/g,btn(t('Save check & return home','जाँच सेव करें और होम पर जाएँ'),'leave-review','full'));}if(flow?.source==='user'){html=html.replaceAll('Cancel payment','Dismiss request').replaceAll('Payment cancelled. You’re in control.','Request dismissed. You’re in control.').replaceAll('No money was sent. This check and your cancellation are saved in demo activity and the analyst dashboard.','Your decision was saved. This website did not execute or cancel a bank transaction.').replaceAll('This is a demo. We never open a payment app or ask for your UPI PIN, OTP, or bank credentials.','We never execute payments or ask for your UPI PIN, OTP, or bank credentials.').replaceAll('We compare your supplied payment details with your message and available independent demo records. Message meaning is an interpretation; account, amount, and payment direction come from the synthetic payment. No private messages or live bank data are accessed.','The decoded payment request supplies the account, amount and intended outgoing direction. The recipient name is unverified. No live bank, merchant directory, device signals or payment history were accessed.');}return html;};
const scenarioPayload=scorePayload;
scorePayload=function(){return {...scenarioPayload(),source:flow.source||'demo'};};
const editScenarioDetails=actions['edit-details'];
actions['edit-details']=()=>{if(flow?.source!=='user')return editScenarioDetails();openModal(t('Edit payment request details','भुगतान अनुरोध बदलें'),t('Changes require a fresh backend check.','बदलाव के बाद नई सर्वर जाँच ज़रूरी है।'),`<form id="user-edit-form"><label class="field-label" for="user-edit-amount">Amount (INR)</label><input id="user-edit-amount" name="amount" type="number" min="0.01" max="1000000" step="0.01" required value="${flow.amount}"><div class="form-row"><label class="field-label" for="user-edit-recipient">Recipient name · unverified</label><input id="user-edit-recipient" name="recipient" maxlength="160" required value="${esc(flow.recipient)}"></div><div class="form-row"><label class="field-label" for="user-edit-account">UPI address</label><input id="user-edit-account" name="account" maxlength="160" pattern="[a-zA-Z0-9._\\-]+@[a-zA-Z0-9._\\-]+" required value="${esc(flow.account)}"></div><div class="button-row"><button class="btn" type="submit">Save & reassess ${icon('refresh')}</button></div></form>`);};
document.addEventListener('submit',async event=>{if(event.target.id!=='user-edit-form')return;event.preventDefault();if(mutationBusy)return;const data=new FormData(event.target),amount=Number(data.get('amount')),recipient=String(data.get('recipient')).trim(),account=String(data.get('account')).trim();if(amount===flow.amount&&recipient===flow.recipient&&account===flow.account){closeModal();return;}try{mutationBusy=true;await updateAction('Recheck required');if(assessment)assessment.invalidated=true;flow.amount=amount;flow.recipient=recipient;flow.account=account;closeModal();}catch(error){toast(error.message);return;}finally{mutationBusy=false;}await analyse();});

const paymentRecordModal=recordModal;
recordModal=function(id){const r=state.records.find(r=>r.id===id);if(!r?.content)return paymentRecordModal(id);lastContentResult=r.content;openModal(esc(contentTitle(r.content)),dateText(r.time)+' · '+esc(r.id),`<p class="microcopy">Review: ${esc(r.review)}</p>${contentResult(r.content)}`);};
const paymentInvestigation=investigation;
investigation=function(){const record=state.records.find(r=>r.id===selectedRecord)||state.records[0];if(!record?.content)return paymentInvestigation();selectedRecord=record.id;lastContentResult=record.content;return `${analystHead('Review the supplied content.','Evidence from a saved backend check. Analyst labels remain separate from model interpretation.')}<div class="content-investigation"><section class="card form-card"><h2>${esc(contentTitle(record.content))}</h2><p class="microcopy">${esc(record.id)} · ${dateText(record.time)} · Review: ${esc(record.review)}</p><div class="decoded-content"><small>SUBMITTED CONTENT</small><pre>${esc(record.message)}</pre></div><div class="review-buttons">${btn('Label fraudulent','review-fraudulent','danger')}${btn('Label legitimate','review-legitimate','secondary')}${btn('Needs investigation','review-investigate','secondary')}</div></section>${contentResult(record.content)}</div>${footer()}`;};

overview=function(){const m=backendMetrics||{},categories={};state.records.forEach(r=>{categories[r.category]=(categories[r.category]||0)+1;});const daily=Array.from({length:7},(_,i)=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-6+i);const end=d.getTime()+86400000;return {label:d.toLocaleDateString('en-IN',{weekday:'short'}),count:state.records.filter(r=>r.time>=d.getTime()&&r.time<end).length};}),max=Math.max(1,...daily.map(d=>d.count));return `${analystHead('A clearer view of every check.','Live records from your backend workspace. Counts include message, QR and payment checks.')}<div class="metric-grid">${metric('Checks recorded',m.total_assessed??0,`${m.message_checks??0} messages · ${m.qr_checks??0} QR inspections`,'transactions')}${metric('Needs attention',m.flagged_transactions??0,'Risk indicators or unverified content','alert')}${metric('Pending reviews',m.pending_reviews??0,'Awaiting analyst judgement','search')}${metric('Warning rate',m.warning_rate??'0%','Across saved checks in this workspace','chart')}</div><div class="chart-grid"><section class="card chart-card"><h2>Checks over the last 7 days</h2><p class="microcopy">Counts from the saved records currently returned by the backend</p><div class="live-bars">${daily.map(d=>`<div><b>${d.count}</b><i style="height:${Math.max(2,d.count/max*110)}px" title="${d.count} check(s)"></i><small>${d.label}</small></div>`).join('')}</div></section><section class="card chart-card"><h2>Recorded categories</h2>${Object.keys(categories).length?Object.entries(categories).sort((a,b)=>b[1]-a[1]).map(([label,n])=>`<div class="contribution"><span>${esc(label)}</span><span>${n}</span><div class="bar"><i style="width:${n/Math.max(1,state.records.length)*100}%"></i></div></div>`).join(''):'<p class="tool-hint">Run a check to see categories here.</p>'}</section></div><div class="section-heading"><h2>Cases awaiting review</h2><button class="text-link" data-page="transactions">View all ${icon('arrow')}</button></div><div class="card table-scroll">${analystTable(state.records.filter(r=>['Pending review','Needs investigation'].includes(r.review)).slice(0,8),true)}</div><p class="microcopy">Payment-model scoring latency: ${m.median_latency_ms==null?'not recorded yet':`median ${esc(m.median_latency_ms)} ms · p95 ${esc(m.p95_latency_ms)} ms`}. AI request latency is shown with each message result.</p>${footer()}`;};

settings=function(){return `<div class="flow-container"><div class="page-head"><div><h1>${t('Make it feel like you.','अपनी पसंद के अनुसार।')}</h1><p>${t('Your preferences. Your clarity.','आपकी पसंद। आपकी स्पष्टता।')}</p></div></div><section class="card settings-group"><h2>${t('Language & accessibility','भाषा और सुलभता')}</h2><div class="setting-row"><div><strong>${t('App language','ऐप की भाषा')}</strong><p>${t('Key screens, warnings and new AI results.','मुख्य स्क्रीन, चेतावनियाँ और नए AI नतीजे।')}</p></div><div class="language-options"><button data-language="en" class="${state.language==='en'?'active':''}">English</button><button data-language="hi" class="${state.language==='hi'?'active':''}">हिन्दी</button></div></div>${toggleSetting('readAloud',t('Read warnings aloud','चेतावनी सुनाएँ'),t('For payment warnings in this browser.','इस ब्राउज़र में भुगतान चेतावनियाँ।'))}${toggleSetting('largeText',t('Larger text','बड़ा पाठ'),t('Increase text size.','पाठ बड़ा करें।'))}${toggleSetting('contrast',t('Higher contrast','अधिक कंट्रास्ट'),t('Make text and controls stand out.','पाठ और बटन स्पष्ट करें।'))}</section><section class="card settings-group"><h2>${t('Your data & connected services','आपका डेटा और सेवाएँ')}</h2><p class="settings-copy">${t('Messages and optional context are sent through the backend to OpenAI. QR images are decoded on your device; only the decoded text is sent for inspection. Checks and analyst decisions are saved in your private backend workspace. Display preferences stay in this browser.','संदेश और संदर्भ सर्वर से OpenAI को जाते हैं। QR तस्वीरें डिवाइस पर पढ़ी जाती हैं; केवल उनका पाठ जाँच के लिए भेजा जाता है। जाँच और फैसले निजी सर्वर कार्यक्षेत्र में सेव होते हैं। पसंद ब्राउज़र में रहती हैं।')}</p><div class="info-note">${icon('lock')}${t('Camera access starts only when you choose Use camera. No bank, private inbox or contact access. No payment is executed.','कैमरा केवल आपके चुनने पर चालू होता है। बैंक, निजी इनबॉक्स या संपर्कों तक पहुँच नहीं। कोई भुगतान नहीं होता।')}</div><p class="settings-copy">${backendMetrics?.ephemeral_storage?t('Free backend hosting can sleep when idle. Check history may reset after a service restart or redeploy.','मुफ़्त सर्वर निष्क्रिय रहने पर सो सकता है। रीस्टार्ट या दोबारा डिप्लॉय होने पर इतिहास मिट सकता है।'):''}</p><div class="button-row">${btn(t('Export my checks','मेरी जाँच निर्यात करें'),'export','secondary','download')}${btn(t('Reconnect services','सेवाओं से फिर जुड़ें'),'retry-backend','secondary','refresh')}</div></section><section class="card settings-group"><h2>${t('A fresh start','नई शुरुआत')}</h2><p class="settings-copy">${t('Delete your message, QR and payment checks, analyst decisions, and candidate selection from this workspace.','इस कार्यक्षेत्र की संदेश, QR और भुगतान जाँच, फैसले व उम्मीदवार चयन हटाएँ।')}</p>${btn(t('Delete my check history','मेरा जाँच इतिहास हटाएँ'),'confirm-reset','secondary','refresh')}</section></div>`;};
actions['notifications']=()=>openModal(t('Your workspace updates','आपके कार्यक्षेत्र की जानकारी'),t('Current saved backend activity.','सर्वर पर सेव मौजूदा गतिविधि।'),`<div class="notification-item">${icon('shield')}<div><strong>${state.records.length} saved check(s)</strong><p>${backendMetrics?.message_checks??0} message checks · ${backendMetrics?.qr_checks??0} QR inspections · ${backendMetrics?.payment_checks??0} payment checks</p></div></div><div class="notification-item">${icon('search')}<div><strong>${state.records.filter(r=>['Pending review','Needs investigation'].includes(r.review)).length} awaiting review</strong><p>Open the analyst dashboard to inspect the supplied evidence.</p></div></div><div class="button-row">${btn('View activity','go-activity','secondary')}${btn('Close','close-modal','secondary')}</div>`);
actions['export']=()=>downloadJSON('upi-guard-checks.json',{notice:'Risk assessments are not proof of authenticity. No payments were executed.',exported_at:new Date().toISOString(),checks:state.records});
const connectedReset=actions['reset'];
actions['reset']=async()=>{await connectedReset();if(!state.records.length){messageResult=null;qrResult=null;lastContentResult=null;messageDraft='';messageContext='';qrDraft='';messageError='';qrError='';render();}};

document.addEventListener('submit',event=>{if(event.target.id==='inspect-link-form'){event.preventDefault();readLink($('#inspect-link').value);}if(event.target.id==='message-check-form'){event.preventDefault();checkMessage();}if(event.target.id==='qr-payload-form'){event.preventDefault();inspectQR($('#qr-payload').value);}if(event.target.id==='user-payment-form'){event.preventDefault();flow.amount=Number($('#user-amount').value);captureForm();analyse();}});
document.addEventListener('input',event=>{if(event.target.id==='scam-message'){messageDraft=event.target.value;const count=$('#message-count');if(count)count.textContent=messageDraft.length+'/5000';}if(event.target.id==='message-context')messageContext=event.target.value;if(event.target.id==='qr-payload')qrDraft=event.target.value;});
document.addEventListener('change',event=>{if(event.target.id==='qr-image')scanImage(event.target.files[0]);});
document.addEventListener('input',event=>{if(['scam-message','message-context'].includes(event.target.id)&&messageResult){messageResult=null;lastContentResult=null;$('#content-result')?.remove();}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState!=='visible')stopCamera();});
window.addEventListener('pagehide',stopCamera);
render();

document.addEventListener('click',event=>{const block=event.target.closest('[data-content-id]');if(block){const r=state.records.find(r=>r.id===block.dataset.contentId);if(r?.content)lastContentResult=r.content;}},true);
actions['go-activity']=()=>{view='consumer';navigate('activity');};
